  renderTemporaryReplyBox() {
    this.domElement = makeElement('div', {
      className: 'comment-node is-temporary-reply',
      'data-node-id': this.id
    });
    this.toggleElement = makeElement('span', { className: 'node-toggle' });

    const app = this.view.options.app;
    const onCancel = () => {
      app.setActiveReplyController(null);
      this.parent.removeChild(this.id);
      this.view.refreshLayout();
    };
    const onPost = () => {
      app.setActiveReplyController(null);
      this.parent.removeChild(this.id);
    };

    const postBox = app.createPostBox(this.parent.id, onPost, onCancel);
    postBox.classList.add('reply-box');

    const contentWrapper = makeElement('div', { className: 'comment-content-wrapper' });
    contentWrapper.appendChild(postBox);
    this.domElement.append(this.toggleElement, contentWrapper);

    setTimeout(() => {
      const focusEl = postBox.querySelector('.username-input') || postBox.querySelector('.comment-input');
      if (focusEl) focusEl.focus();
    }, 50);

    return this.domElement;
  }

  removeChild(childId) {
    const childIndex = this.children.findIndex((c) => c.id === childId);
    if (childIndex > -1) {
      const [removedNode] = this.children.splice(childIndex, 1);
      this.view._unregisterNode(removedNode);
    }
    this.updateVisualState();
    this.updateToggleIcon();
  }

  setCollapsed(isCollapsed) {
    if (this.isCollapsed === isCollapsed || !this.domElement) return;
    this.isCollapsed = isCollapsed;
    this.domElement.classList.toggle('is-collapsed', this.isCollapsed);
  }

  updateTextPreview() {
    if (!this.textPreviewElement) return;
    if (this.isDeleted) {
      this.textPreviewElement.textContent = '';
      return;
    }
    const previewText = this.text.replace(/\n/g, ' ').trim();
    this.textPreviewElement.textContent = ` - ${previewText}`;
  }

  setProminence(val) {
    this.prominence = Math.max(0, Math.min(100, Math.round(val)));
    if (this.domElement) {
      const tier = this.prominence >= 80 ? 'high' : (this.prominence <= 45 ? 'diminished' : 'normal');
      this.domElement.setAttribute('data-prominence', tier);
      if (this.prominenceBadge) {
        this.prominenceBadge.textContent = `${this.prominence}% Prominence`;
      }
      if (this.view) this.view.refreshLayout();
    }
  }

  showEditBox() {
      if (!this.textBodyElement || this._editingBox) return;
      const app = this.view.options.app;
      const ta = makeElement('textarea', {
        className: 'comment-input',
        style: { width: '100%', minHeight: '64px', marginTop: '6px', boxSizing: 'border-box' }
      });
      ta.value = this.text;

      const saveBtn = makeElement('button', {
        type: 'button',
        className: 'post-button',
        style: { padding: '5px 12px', fontSize: '12px' },
        onclick: async (e) => {
          e.stopPropagation();
          const nextText = ta.value.trim();
          if (!nextText) return;
          const res = await app.serverAPI.editComment(this.id, app.currentUser?.id, nextText, app.threadId);
          if (res && res.success) {
            this.text = nextText;
            this.updateTextPreview();
            this.textBodyElement.textContent = nextText;
            this.textBodyElement.style.display = '';
            this._editingBox.remove();
            this._editingBox = null;
            this.view.refreshLayout();
          } else {
            alert(res?.error || 'Could not update comment.');
          }
        }
      }, 'Save');

      const cancelBtn = makeElement('button', {
        type: 'button',
        className: 'cancel-button',
        style: { padding: '5px 10px', fontSize: '12px' },
        onclick: (e) => {
          e.stopPropagation();
          this.textBodyElement.style.display = '';
          this._editingBox.remove();
          this._editingBox = null;
          this.view.refreshLayout();
        }
      }, 'Cancel');

      this._editingBox = makeElement('div', {
        style: { display: 'flex', flexDirection: 'column', gap: '6px', marginTop: '4px' }
      }, [
        ta,
        makeElement('div', { style: { display: 'flex', justifyContent: 'flex-end', gap: '6px' } }, [cancelBtn, saveBtn])
      ]);

      this.textBodyElement.style.display = 'none';
      this.textBodyElement.parentElement.appendChild(this._editingBox);
      this.view.refreshLayout();
      setTimeout(() => ta.focus(), 20);
    }
